def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = me.count('C')
    my_d = n - my_c

    r5d = opp[-5:].count('D')
    r8d = opp[-8:].count('D')
    r10d = opp[-10:].count('D')

    d_streak = 0
    for x in reversed(opp):
        if x == 'D':
            d_streak += 1
        else:
            break

    c_streak = 0
    for x in reversed(opp):
        if x == 'C':
            c_streak += 1
        else:
            break

    dd_run = 0
    if last_me == 'D' and last_opp == 'D':
        for i in reversed(range(n)):
            if me[i] == 'D' and opp[i] == 'D':
                dd_run += 1
            else:
                break

    after_D_C = 0
    after_D_D = 0
    after_C_D = 0
    after_C_C = 0
    match = 0

    for i in range(1, n):
        prev = me[i - 1]
        cur = opp[i]
        if prev == 'D':
            if cur == 'C':
                after_D_C += 1
            else:
                after_D_D += 1
        else:
            if cur == 'D':
                after_C_D += 1
            else:
                after_C_C += 1
        if cur == prev:
            match += 1

    recip_rate = match / (n - 1) if n > 1 else 0.0

    chronic = (
        d_streak >= 8 or
        r10d >= 8 or
        (n >= 30 and opp_d >= 20 and r10d >= 7)
    )

    exploitable = (
        after_D_C >= 1 and
        after_D_C > after_D_D and
        opp_c >= 3
    )

    retaliatory = (
        after_D_D >= 3 and
        after_D_D >= after_D_C
    )

    independent_periodic = False
    if n >= 16 and opp_c >= 2 and opp_d >= 2 and 2 <= r10d <= 8:
        window = 24
        if n < window:
            window = n
        start = n - window
        best_rate = 0.0
        for L in range(2, 9):
            if n - L <= start:
                continue
            ok = 0
            tot = 0
            for i in range(start + L, n):
                tot += 1
                if opp[i] == opp[i - L]:
                    ok += 1
            if tot >= 6 and ok / tot > best_rate:
                best_rate = ok / tot
        if best_rate >= 0.80 and recip_rate < 0.68 and not retaliatory:
            independent_periodic = True

    if chronic:
        if c_streak >= 6 and r10d <= 2:
            return 'C'
        return 'D'

    if independent_periodic:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if d_streak >= 6 or r10d >= 7:
                return 'D'
            if exploitable and rng.random() < 0.25:
                return 'D'
            return 'C'

        if d_streak == 1:
            return 'C'

        if d_streak <= 4 and n >= 2 and me[-2] == 'D':
            if d_streak <= 3 or r10d <= 4:
                return 'C'

        if d_streak == 2:
            return 'D'

        if d_streak >= 3:
            if exploitable:
                return 'D' if rng.random() < 0.55 else 'C'
            if r8d >= 3 or after_C_D >= 2 or (n >= 2 and me[-2] == 'C'):
                return 'D'
            return 'C'

    if last_me == 'D':
        if exploitable and rng.random() < 0.45:
            return 'D'
        return 'C'

    if c_streak >= (3 if exploitable else 5) and n >= 20:
        if exploitable:
            p = 0.35 if n < 80 else 0.55
        elif retaliatory:
            p = 0.02
        elif my_d == 0:
            p = 0.05
        elif opp_d <= 3 and opp_c >= 30:
            p = 0.12
        else:
            p = 0.08
        if rng.random() < p:
            return 'D'

    return 'C'
